inputs = ['zcaiax', 'ahyzx', 'wghx', 'zfv', 'uygeck']
outputs = ['yjcaiax', 'awkjx', 'wagwx', 'yjfv', 'uygeck']

# Let me analyze what happens at each position across all inputs
print("Position analysis:")
max_len = max(len(s) for s in inputs + outputs)

for pos in range(max_len):
    print(f"\nPosition {pos}:")
    changes = {}
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if pos < len(inp) and pos < len(out):
            if inp[pos] != out[pos]:
                changes[inp[pos]] = out[pos]
        elif pos < len(inp):
            # Character deleted
            print(f"  Input '{inp[pos]}' removed at position {pos}")
        elif pos < len(out):
            # Character added
            print(f"  New character '{out[pos]}' added at position {pos}")

    if changes:
        print(f"  Changes: {changes}")

# Let's look for common substitution patterns
print("\nLooking for substitution patterns:")
patterns = {}

# Check for single character replacements
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        for pos in range(min(len(inp), len(out))):
            if inp[pos] != out[pos]:
                pattern = inp[pos]
                replacement = out[pos]
                if pattern not in patterns:
                    patterns[pattern] = replacement
                elif patterns[pattern] != replacement:
                    print(f"Conflict: '{pattern}' maps to both '{patterns[pattern]}' and '{replacement}'")

print("Potential patterns:", patterns)

